    "cssVarsLabel": "Variables CSS",
    "jsHint": "Le code JS doit renvoyer un objet comme valeur de retour de setup du composant Vue. Utilisez ctx.api.get('/me') pour appeler l'API backend. Après l'enregistrement, ouvrez la page du portail pour voir le rendu réel.",
    "ctxApiRefBody": "ctx.ref(val)              — Crée une variable réactive\nctx.computed(fn)          — Crée une propriété calculée\nctx.watch(src, cb)        — Surveille les changements\nctx.onMounted(fn)         — Lors du montage du composant\nctx.onUnmounted(fn)       — Lors du démontage du composant\n\nctx.data.client           — Informations du compte utilisateur (réactif)\nctx.data.token            — Token actuel (réactif)\nctx.data.isDark           — Mode sombre (réactif)\n\nctx.api.get(path, query)  — Requête GET\nctx.api.post(path, body)  — Requête POST\nctx.api.put(path, body)   — Requête PUT\nctx.api.delete(path)      — Requête DELETE\n\nctx.formatBytes(bytes)    — Formate une taille de fichier\nctx.formatDate(date)      — Formate une date\nctx.copyText(text)        — Copier dans le presse-papiers\nctx.elMessage             — Message Element Plus\nctx.config                — Configuration du portail (PORTAL_CONFIG)\nctx.moduleId              — ID du module actuel\nctx.moduleTitle           — Titre du module actuel",
